import Foundation

// MARK: - Reine Entscheidungen des Verlaufs (ohne AppKit, ohne Dateien)

enum ClipboardHistoryCore {
    // MARK: Erfassen oder verwerfen

    enum SkipReason: String, Equatable, Sendable {
        case disabled
        case paused
        case internalWrite
        case confidential
        case excludedApp
        case empty
        case tooLarge
    }

    enum CaptureDecision: Equatable, Sendable {
        case store
        case skip(SkipReason)
    }

    /// Typen, die außer den nspasteboard.org-Markierungen (Concealed, Transient,
    /// AutoGenerated) Vertrauliches oder Zwischenstände kennzeichnen. Dieselbe
    /// Liste nutzt Maccy; ältere Passwort-Manager setzen nur ihren eigenen Typ.
    static let ignoredTypes: Set<String> = [
        "com.agilebits.onepassword",
        "net.antelle.keeweb",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    /// Entscheidet, ob ein Inhalt in den Verlauf darf. Reihenfolge ist
    /// Absicht: Vertrauliches wird nie gespeichert, egal woher es kommt.
    static func decide(
        enabled: Bool,
        paused: Bool,
        isInternalWrite: Bool,
        types: [String],
        sourceBundleID: String?,
        excludedApps: Set<String>
    ) -> CaptureDecision {
        if !enabled { return .skip(.disabled) }
        if paused { return .skip(.paused) }
        if isInternalWrite || types.contains(ClipboardInternalMarker.typeName) { return .skip(.internalWrite) }
        if PasteboardPrivacy.isConfidential(types) || types.contains(where: ignoredTypes.contains) {
            return .skip(.confidential)
        }
        if let id = sourceBundleID?.lowercased(), excludedApps.contains(where: { $0.lowercased() == id }) {
            return .skip(.excludedApp)
        }
        return .store
    }

    // MARK: Einfügen mit Duplikat-Erkennung

    /// Fügt `entry` oben ein. Gibt es den Inhalt schon, wandert der alte
    /// Eintrag nach oben (Pin, ID und erste Kopierzeit bleiben, die Zähler
    /// laufen weiter) und `entry` wird verworfen.
    /// `replacedBlobs` nennt Dateien des verworfenen neuen Eintrags, die nicht
    /// gebraucht werden.
    static func insert(
        _ entry: ClipboardEntry,
        into entries: [ClipboardEntry]
    ) -> (entries: [ClipboardEntry], merged: Bool, discardedBlobs: [String]) {
        var list = entries
        if let index = list.firstIndex(where: { $0.contentHash == entry.contentHash && $0.kind == entry.kind }) {
            var existing = list.remove(at: index)
            existing.lastCopiedAt = entry.lastCopiedAt
            existing.copyCount += 1
            if entry.sourceBundleID != nil {
                existing.sourceBundleID = entry.sourceBundleID
                existing.sourceName = entry.sourceName
            }
            // Wurde ein schon kopierter Text diktiert, ist er jetzt ein Diktat:
            // Modus und Roh-Transkript des neuen Eintrags gehen mit.
            if entry.dictationMode != nil {
                existing.dictationMode = entry.dictationMode
                existing.dictationOriginal = entry.dictationOriginal ?? existing.dictationOriginal
            }
            list.insert(existing, at: 0)
            // Blob-Dateien des neuen Eintrags wären Dubletten der vorhandenen.
            return (list, true, entry.blobFiles.filter { !existing.blobFiles.contains($0) })
        }
        list.insert(entry, at: 0)
        return (list, false, [])
    }

    // MARK: Kürzen

    /// Hält höchstens `maxUnpinned` nicht angepinnte Einträge (die neuesten).
    /// Angepinnte zählen nicht mit und bleiben immer.
    /// `maxUnpinnedBytes` begrenzt zusätzlich den Platz der Dateien (Bilder,
    /// Archive): Wird er überschritten, fallen die ältesten nicht angepinnten
    /// Einträge weg. Der neueste Eintrag bleibt immer.
    static func trim(
        _ entries: [ClipboardEntry],
        maxUnpinned: Int,
        maxUnpinnedBytes: Int = .max
    ) -> (kept: [ClipboardEntry], removed: [ClipboardEntry]) {
        let limit = max(1, maxUnpinned)
        let newestFirst = entries.sorted { $0.lastCopiedAt > $1.lastCopiedAt }
        var seenUnpinned = 0
        var bytes = 0
        var removedIDs = Set<String>()
        for entry in newestFirst where !entry.isPinned {
            seenUnpinned += 1
            bytes += entry.diskBytes
            if seenUnpinned > limit || (seenUnpinned > 1 && bytes > maxUnpinnedBytes) {
                removedIDs.insert(entry.id)
                bytes -= entry.diskBytes
            }
        }
        let kept = entries.filter { !removedIDs.contains($0.id) }
        let removed = entries.filter { removedIDs.contains($0.id) }
        return (kept, removed)
    }

    // MARK: Reihenfolge

    /// Chronologisch, neuester zuerst: Grundlage der CLI-Nummern (1 = neuester).
    static func chronological(_ entries: [ClipboardEntry]) -> [ClipboardEntry] {
        entries.sorted {
            if $0.lastCopiedAt != $1.lastCopiedAt { return $0.lastCopiedAt > $1.lastCopiedAt }
            return $0.id < $1.id
        }
    }

    /// Anzeige im Fenster: Angepinnte oben, jeweils neuester zuerst.
    static func displayOrder(_ entries: [ClipboardEntry]) -> [ClipboardEntry] {
        let ordered = chronological(entries)
        return ordered.filter(\.isPinned) + ordered.filter { !$0.isPinned }
    }

    // MARK: Nummer oder ID auflösen

    enum ResolveError: Error, Equatable {
        case notFound(String)
        case ambiguous(String)
        case outOfRange(Int, Int)
    }

    /// `ref` ist eine Nummer (1 = neuester Eintrag) oder eine ID bzw. ein
    /// eindeutiges Präfix davon (ab vier Zeichen).
    static func resolve(_ ref: String, in entries: [ClipboardEntry]) -> Result<ClipboardEntry, ResolveError> {
        let ordered = chronological(entries)
        let trimmed = ref.trimmingCharacters(in: .whitespaces)
        let needle = trimmed.lowercased()
        // Reine Zahl im Bereich = Nummer. Eine Zahl außerhalb gilt nur als
        // ID-Präfix, wenn sie vier Zeichen oder länger ist (IDs sind Hex).
        if let number = Int(trimmed) {
            if number >= 1, number <= ordered.count { return .success(ordered[number - 1]) }
            if needle.count < 4 { return .failure(.outOfRange(number, ordered.count)) }
        }
        guard needle.count >= 4 else { return .failure(.notFound(ref)) }
        let matches = ordered.filter { $0.id.lowercased().hasPrefix(needle) }
        switch matches.count {
        case 0: return .failure(.notFound(ref))
        case 1: return .success(matches[0])
        default: return .failure(.ambiguous(ref))
        }
    }

    // MARK: Suche

    /// Suche beim Tippen: Groß/Klein und Diakritika egal, jedes Wort der
    /// Eingabe muss vorkommen. Treffer weiter vorn und auf Wortanfängen
    /// ranken höher, bei Gleichstand der neuere Eintrag.
    /// `haystack` liefert den vorbereiteten Suchtext (`ClipboardSearchIndex`);
    /// so läuft beim Tippen kein Datei-Zugriff und kein Falten langer Texte.
    static func search(
        _ entries: [ClipboardEntry],
        query: String,
        haystack: (ClipboardEntry) -> [UInt8]
    ) -> [ClipboardEntry] {
        let terms = ClipboardSearchIndex.fold(query)
            .split(whereSeparator: \.isWhitespace)
            .map { Array($0.utf8) }
        guard !terms.isEmpty else { return displayOrder(entries) }

        var scored: [(entry: ClipboardEntry, score: Int)] = []
        for entry in entries {
            let bytes = haystack(entry)
            var total = 0
            var matchedAll = true
            for term in terms {
                guard let position = ClipboardSearchIndex.firstIndex(of: term, in: bytes) else {
                    matchedAll = false
                    break
                }
                var score = 1000 - min(position, 900)
                if position == 0 {
                    score += 200
                } else if !isWordCharacter(bytes[position - 1]) {
                    score += 80
                }
                total += score
            }
            if matchedAll { scored.append((entry, total + (entry.isPinned ? 25 : 0))) }
        }
        return scored.sorted {
            if $0.score != $1.score { return $0.score > $1.score }
            if $0.entry.lastCopiedAt != $1.entry.lastCopiedAt { return $0.entry.lastCopiedAt > $1.entry.lastCopiedAt }
            return $0.entry.id < $1.entry.id
        }.map(\.entry)
    }

    /// Suche ohne fertigen Index (CLI, Tests): baut den Suchtext je Eintrag aus `fullText`.
    static func search(
        _ entries: [ClipboardEntry],
        query: String,
        fullText: (ClipboardEntry) -> String? = { $0.text }
    ) -> [ClipboardEntry] {
        search(entries, query: query) { entry in
            ClipboardSearchIndex.haystack(for: entry, fullText: entry.kind == .text ? fullText(entry) : nil)
        }
    }

    /// Buchstabe oder Ziffer in UTF-8; Bytes ab 0x80 gehören zu Umlauten und Co.
    private static func isWordCharacter(_ byte: UInt8) -> Bool {
        switch byte {
        case 0x30...0x39, 0x41...0x5A, 0x61...0x7A, 0x80...0xFF: return true
        default: return false
        }
    }
}

/// Marker, mit dem die App eigene Schreibvorgänge auf der Zwischenablage
/// kennzeichnet (Einfügen aus dem Verlauf, Diktat-Paste). Der Monitor ignoriert
/// solche Inhalte; andere Apps sehen nur einen unbekannten Typ.
enum ClipboardInternalMarker {
    static let typeName = "com.whisperm8.app.clipboard-internal"
}

// MARK: - Diktat-Ergebnisse

extension ClipboardHistoryCore {
    /// Typen, die ein Diktat in die Zwischenablage legt (reiner Text).
    static let dictationTypes = ["public.utf8-plain-text"]

    /// Baut aus einem fertigen Diktat den Verlaufseintrag, oder `nil`, wenn er
    /// nicht hineingehört: Verlauf aus oder pausiert, leerer Text, oder das
    /// Diktat ging in eine ausgeschlossene App (etwa einen Passwort-Manager).
    /// Herkunft ist die App, in die diktiert wurde. `original` ist das
    /// Roh-Transkript; es wird nur behalten, wenn es sich vom Ergebnis
    /// unterscheidet und nicht übermäßig lang ist.
    static func dictationCapture(
        text: String,
        original: String? = nil,
        modeName: String,
        targetBundleID: String?,
        targetName: String?,
        settings: ClipboardSettings,
        date: Date = Date()
    ) -> ClipboardCapture? {
        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return nil }
        let decision = decide(
            enabled: settings.enabled, paused: settings.paused, isInternalWrite: false,
            types: dictationTypes, sourceBundleID: targetBundleID,
            excludedApps: Set(settings.excludedApps)
        )
        guard decision == .store else { return nil }
        return ClipboardCapture(
            types: dictationTypes, text: text,
            sourceBundleID: targetBundleID, sourceName: targetName,
            date: date, dictationMode: modeName,
            dictationOriginal: keptOriginal(original, text: text)
        )
    }

    /// Längstes Roh-Transkript, das neben dem Ergebnis gespeichert wird.
    static let maxDictationOriginalChars = 100_000

    static func keptOriginal(_ original: String?, text: String) -> String? {
        guard let original else { return nil }
        let trimmed = original.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, trimmed.count <= maxDictationOriginalChars,
              trimmed != text.trimmingCharacters(in: .whitespacesAndNewlines) else { return nil }
        return trimmed
    }
}
